package com.johnny.hotel;import com.johnny.hotel.financeexpense.*;import com.johnny.hotel.support.WalletDevelopmentGuard;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfSystemProperty;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.dao.DataAccessException;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.*;import java.math.*;import java.time.*;import java.util.*;import java.util.concurrent.*;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest(classes=HotelBackendApplication.class,properties={"hotel.wallet.dev.fixture=true","spring.cache.type=none","logging.level.org.springframework=WARN"})@EnabledIfSystemProperty(named="hotel.wallet.dev.tests",matches="true")class HotelExpenseDevelopmentTest{
 @DynamicPropertySource static void props(DynamicPropertyRegistry r){var e=WalletDevelopmentGuard.settings();r.add("spring.datasource.url",WalletDevelopmentGuard::url);r.add("spring.datasource.username",()->e.get("DB_USERNAME"));r.add("spring.datasource.password",()->e.get("DB_PASSWORD"));r.add("spring.data.redis.password",()->e.get("REDIS_PASSWORD"));}
 @Autowired HotelExpenseService service;@Autowired JdbcTemplate jdbc;
 @Test void fullLifecycleConcurrentPayAndDatabaseImmutability()throws Exception{long creator=user("OWNER"),approver=userOther("SUPER_ADMIN",creator);String key="expense-"+UUID.randomUUID(),submit="submit-"+UUID.randomUUID(),approve="approve-"+UUID.randomUUID(),pay="payment-"+UUID.randomUUID();var e=service.create(new ExpenseCommands.Create(new BigDecimal("73.25"),"CNY",ExpenseCategory.SUPPLIES,"targeted expense test",null,LocalDate.now(),null,null,null,null,key),creator);assertEquals(0,e.getStatus());assertThrows(RuntimeException.class,()->service.approve(e.getId(),new ExpenseCommands.Action(approve,null),creator));service.submit(e.getId(),new ExpenseCommands.Action(submit,null),creator);service.approve(e.getId(),new ExpenseCommands.Action(approve,null),approver);var pool=Executors.newFixedThreadPool(2);try{var cmd=new ExpenseCommands.Pay(pay,"BANK_TRANSFER","expense-test-ref-"+e.getId());var a=pool.submit(()->service.pay(e.getId(),cmd,approver));var b=pool.submit(()->service.pay(e.getId(),cmd,approver));assertEquals(3,a.get(10,TimeUnit.SECONDS).getStatus());assertEquals(3,b.get(10,TimeUnit.SECONDS).getStatus());}finally{pool.shutdownNow();}assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM hotel_transaction_record WHERE source_type='EXPENSE' AND source_id=? AND direction='EXTERNAL_OUT'",Integer.class,e.getId()));assertNotNull(jdbc.queryForObject("SELECT posting_business_date FROM hotel_expense WHERE id=?",LocalDate.class,e.getId()));assertNotNull(jdbc.queryForObject("SELECT paid_at FROM hotel_expense WHERE id=?",LocalDateTime.class,e.getId()));assertThrows(DataAccessException.class,()->jdbc.update("UPDATE hotel_expense SET amount=99 WHERE id=?",e.getId()));}
 @Test void rejectedExpenseNeverCreatesMoneyMovement(){long creator=user("OWNER"),approver=userOther("SUPER_ADMIN",creator);String key="expense-"+UUID.randomUUID();var e=service.create(new ExpenseCommands.Create(new BigDecimal("11.00"),"CNY",ExpenseCategory.OTHER,"rejected expense test",null,LocalDate.now(),null,null,null,null,key),creator);service.submit(e.getId(),new ExpenseCommands.Action("submit-"+UUID.randomUUID(),null),creator);service.reject(e.getId(),new ExpenseCommands.Action("reject-"+UUID.randomUUID(),"not authorized"),approver);assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM hotel_transaction_record WHERE source_type='EXPENSE' AND source_id=?",Integer.class,e.getId()));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM revenue_recognition WHERE source_type='EXPENSE' AND source_id=?",Integer.class,e.getId()));}
 @Test void partialAndFullReversalsAreAppendOnlyAndCashOnly()throws Exception{long creator=user("OWNER"),other=userOther("SUPER_ADMIN",creator);String key="expense-"+UUID.randomUUID();var e=service.create(new ExpenseCommands.Create(new BigDecimal("120.00"),"CNY",ExpenseCategory.VENDOR,"reversal target",null,LocalDate.now(),null,null,null,null,key),creator);service.submit(e.getId(),new ExpenseCommands.Action("submit-"+UUID.randomUUID(),null),creator);service.approve(e.getId(),new ExpenseCommands.Action("approve-"+UUID.randomUUID(),null),other);service.pay(e.getId(),new ExpenseCommands.Pay("payment-"+UUID.randomUUID(),"BANK_TRANSFER","vendor-payment"),other);
  var first=service.requestReversal(e.getId(),new ExpenseReversalCommands.Request(new BigDecimal("20.00"),"supplier returned funds","reverse-"+UUID.randomUUID()),other);assertThrows(RuntimeException.class,()->service.approveReversal(first.getId(),new ExpenseReversalCommands.Approve("reverse-approve-self",true,"refund-a"),other));var pool=Executors.newFixedThreadPool(2);try{var command=new ExpenseReversalCommands.Approve("reverse-approve-"+UUID.randomUUID(),true,"refund-a");var a=pool.submit(()->service.approveReversal(first.getId(),command,creator));var b=pool.submit(()->service.approveReversal(first.getId(),command,creator));assertEquals(1,a.get(10,TimeUnit.SECONDS).getStatus());assertEquals(1,b.get(10,TimeUnit.SECONDS).getStatus());}finally{pool.shutdownNow();}
  var rejected=service.requestReversal(e.getId(),new ExpenseReversalCommands.Request(new BigDecimal("5.00"),"refund did not arrive","reverse-"+UUID.randomUUID()),other);service.rejectReversal(rejected.getId(),new ExpenseReversalCommands.Reject("reverse-reject-"+UUID.randomUUID(),"No real funds were returned"),creator);assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM hotel_transaction_record WHERE source_type='EXPENSE_REVERSAL' AND source_id=?",Integer.class,rejected.getId()));var second=service.requestReversal(e.getId(),new ExpenseReversalCommands.Request(new BigDecimal("100.00"),"remaining supplier refund","reverse-"+UUID.randomUUID()),other);service.approveReversal(second.getId(),new ExpenseReversalCommands.Approve("reverse-approve-"+UUID.randomUUID(),true,"refund-b"),creator);var detail=service.detail(e.getId(),creator);assertEquals(new BigDecimal("120.00"),detail.getReversedAmount());assertEquals(BigDecimal.ZERO.setScale(2),detail.getNetCashExpense());assertTrue(detail.isFullyReversed());assertEquals(2,jdbc.queryForObject("SELECT COUNT(*) FROM hotel_transaction_record WHERE source_type='EXPENSE_REVERSAL' AND business_reference_id=? AND direction='EXTERNAL_IN'",Integer.class,e.getId()));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM revenue_recognition WHERE source_type='EXPENSE_REVERSAL'",Integer.class));assertThrows(RuntimeException.class,()->service.requestReversal(e.getId(),new ExpenseReversalCommands.Request(new BigDecimal("0.01"),"exceeds paid amount","reverse-"+UUID.randomUUID()),other));}
 private long user(String role){return jdbc.queryForObject("SELECT u.id FROM sys_user u JOIN sys_user_role ur ON ur.user_id=u.id JOIN sys_role r ON r.id=ur.role_id WHERE u.status=1 AND r.role_code=? ORDER BY u.id LIMIT 1",Long.class,role);}private long userOther(String role,long other){return jdbc.queryForObject("SELECT u.id FROM sys_user u JOIN sys_user_role ur ON ur.user_id=u.id JOIN sys_role r ON r.id=ur.role_id WHERE u.status=1 AND r.role_code=? AND u.id<>? ORDER BY u.id LIMIT 1",Long.class,role,other);}
}
